// Base URL where repo image paths are hosted (append relative paths returned by API)
const IMAGE_BASE = import.meta.env.VITE_REPO_BASE ? `${import.meta.env.VITE_REPO_BASE}/` : 'https://icmeprod.excelsoftcorp.com/ICME/ICME_repo/'

// Pages can be read from Azure blob storage with a SAS token instead of the repo
// host. VITE_BLOB_ENABLED is the switch; VITE_BLOB_REPO_CYCLE then narrows it to
// one cycle, or serves every cycle from blob when left blank. With the switch off
// nothing else here matters and every image comes from IMAGE_BASE.
const BLOB_REPO_ENABLED = /^(1|true|yes|on)$/i.test(String(import.meta.env.VITE_BLOB_ENABLED ?? '').trim())
const BLOB_REPO_CYCLE = String(import.meta.env.VITE_BLOB_REPO_CYCLE || '').trim()
const BLOB_REPO_BASE = String(import.meta.env.VITE_BLOB_REPO_BASE || '').trim().replace(/\/+$/, '')
const BLOB_REPO_PREFIX = String(import.meta.env.VITE_BLOB_REPO_PREFIX || '').trim().replace(/^\/+|\/+$/g, '')
const BLOB_REPO_SAS = String(import.meta.env.VITE_BLOB_REPO_SAS || '').trim().replace(/^\?/, '')

/**
 * The Year and Cycle the Home page stored when the subject was picked. Uploads
 * are scoped by them, so they travel with the file rather than being inferred
 * from the workspace server-side.
 */
const getActiveYearCycle = () => {
  try {
    return {
      year: (sessionStorage.getItem('yearcode') || sessionStorage.getItem('yearCode') || '').trim(),
      cycle: (sessionStorage.getItem('cyclecode') || sessionStorage.getItem('cycleCode') || '').trim(),
    }
  } catch {
    return { year: '', cycle: '' }
  }
}

/** True when this page's images should come from blob storage rather than the repo. */
const isBlobRepoCycle = () => {
  if (!BLOB_REPO_ENABLED || !BLOB_REPO_BASE) return false
  // No cycle named: blob serves them all.
  if (!BLOB_REPO_CYCLE) return true
  try {
    const active = (sessionStorage.getItem('cyclecode') || sessionStorage.getItem('cycleCode') || '').trim()
    return active.toLowerCase() === BLOB_REPO_CYCLE.toLowerCase()
  } catch {
    return false
  }
}

/**
 * Turns a repo-relative page path into a URL the browser can load.
 *
 * The API answers with "ICME/ICME_Prod/<subject>/<workspace>/<reg>/1.png". The
 * repo host takes that path appended to its base as-is. Blob storage needs two
 * adjustments: blob names are case-sensitive and the upload wrote that root
 * folder lowercase, so the leading segment is replaced with the spelling that
 * actually exists (VITE_BLOB_REPO_PREFIX); and the SAS has to follow the blob
 * path as the query string rather than sit in the middle of the URL.
 *
 * Only spaces and the like are escaped - encodeURI leaves '&' alone, which
 * matters because subject folders are named "Economics & Hospitality".
 */
const buildRepoImageUrl = (relativePath: string) => {
  const cleaned = String(relativePath ?? '').replace(/^\/+/, '')
  if (!isBlobRepoCycle()) {
    return `${IMAGE_BASE.replace(/\/+$/, '')}/${encodeURI(cleaned)}`
  }
  const segments = cleaned.split('/')
  if (BLOB_REPO_PREFIX) {
    if (segments[0]?.toLowerCase() === BLOB_REPO_PREFIX.toLowerCase()) segments.shift()
    segments.unshift(BLOB_REPO_PREFIX)
  }
  const blobUrl = `${BLOB_REPO_BASE}/${encodeURI(segments.join('/'))}`
  return BLOB_REPO_SAS ? `${blobUrl}?${BLOB_REPO_SAS}` : blobUrl
}

// Recursively remove null bytes from all string values to prevent WIN1252 encoding errors
const sanitizePayload = (obj: any): any => {
  if (typeof obj === 'string') return obj.replace(/\x00/g, '')
  if (Array.isArray(obj)) return obj.map(sanitizePayload)
  if (obj && typeof obj === 'object') return Object.fromEntries(Object.entries(obj).map(([k, v]) => [k, sanitizePayload(v)]))
  return obj
}

