// Language hint sent with every video transcription request; overridable per
// deployment since the transcription service does not auto-detect it.
const VIDEO_TRANSCRIBE_LANGUAGE = import.meta.env.VITE_VIDEO_TRANSCRIBE_LANGUAGE || 'en'

/**
 * Sends one recorded/uploaded video's audio track straight to the
 * transcribeAudioDirect service and returns its transcript text.
 *
 * Only the plain `text` field is kept - diarization and word-level timing the
 * service also returns is kept alongside it under `segments`, so a speaker-
 * by-speaker breakdown stays available even though today's OCR text display
 * only reads `text`.
 */
interface VideoTranscriptionResult {
  text: string
  segments: Array<{
    text: string
    start: number
    end: number
    confidence?: number
    speaker?: string
    words?: Array<{ text: string; start: number; end: number; confidence?: number; speaker?: string }>
  }>
}

const transcribeVideoFile = async (file: File): Promise<VideoTranscriptionResult> => {
  const form = new FormData()
  form.append('file', file)
  form.append('language', VIDEO_TRANSCRIBE_LANGUAGE)
  form.append('diarization', 'true')
  form.append('keyterms', '')
  const res = await axios.post(API_ENDPOINTS.transcribeAudioDirect, form, {
    headers: { 'Content-Type': 'multipart/form-data' },
  })
  if (!res || res.status < 200 || res.status >= 300) {
    throw new Error(res?.data?.message || `Failed to transcribe ${file.name}`)
  }
  return {
    text: String(res.data?.text ?? ''),
    segments: Array.isArray(res.data?.segments) ? res.data.segments : [],
  }
}

