const toDisplayableImageUrl = (rawPath: string): string => {
  const path = String(rawPath ?? '').trim()
  if (!path) return ''

  // Already a usable URL
  if (/^(https?:\/\/|data:|blob:)/i.test(path)) return path

  // Windows absolute path -> file URL
  // Example: C:\Users\x\file.png -> file:///C:/Users/x/file.png
  if (/^[a-zA-Z]:\\/.test(path)) {
    const normalized = path.replace(/\\/g, '/')
    return `file:///${encodeURI(normalized)}`
  }

  // UNC path -> file URL
  // Example: \\server\share\file.png -> file://server/share/file.png
  if (/^\\\\/.test(path)) {
    const withoutLeading = path.replace(/^\\\\/, '')
    const normalized = withoutLeading.replace(/\\/g, '/')
    return `file://${encodeURI(normalized)}`
  }

  // If the API returned a relative repo path (for example: "ICME/.../1.png"),
  // prepend the public IMAGE_BASE so the browser can load it over HTTP.
  // Avoid prepending when the path already has a protocol or is a file/UNC path.
  if (!/^(https?:\/\/|data:|blob:|file:\/\/|[a-zA-Z]:\\\\|\\\\)/i.test(path)) {
    return buildRepoImageUrl(path)
  }

  // Fallback: return as-is
  return path
}

