/**
 * Reads the OCR text one question holds for one image.
 *
 * The same image may be tagged to several questions, and each question keeps its
 * own (independently edited) text for it. Callers that rebuild the per-question
 * OCR map must therefore read the question's own entry rather than a map keyed by
 * image path alone, which would copy one question's text onto every other
 * question sharing that image. Returns null when the question has no entry for
 * the image, so the caller can fall back for images it has no text for yet.
 */
const readQuestionOcrText = (
  byQuestion: Record<string, Record<string, any>> | null | undefined,
  questionKey: string,
  imagePath: string,
): string | null => {
  const perQuestion = byQuestion?.[questionKey]
  if (!perQuestion || typeof perQuestion !== 'object') return null
  if (!Object.prototype.hasOwnProperty.call(perQuestion, imagePath)) return null
  const value = (perQuestion as Record<string, any>)[imagePath]
  return (value !== null && typeof value === 'object')
    // transcription: image OCR's ExtractionResult shape. text: video's
    // VideoTranscriptionResult shape (added for Video upload mode).
    ? String((value as any).transcription ?? (value as any).text ?? '')
    : String(value ?? '')
}

