  const fetchConfig = React.useCallback(async () => {
    setIsConfigLoading(true);
    setIsConfigError(false);
    try {
      const orgCode = sessionStorage.getItem('orgCode') || sessionStorage.getItem('orgcode') || 'ICMELIVE';
      const custCode = sessionStorage.getItem('customerCode') || sessionStorage.getItem('custcode') || sessionStorage.getItem('custCode') || 'ICME';
      const baseUrl = import.meta.env.VITE_AIMARKING_API_BASE || (typeof API_BASE1 !== 'undefined' ? API_BASE1 : '') || 'https://icmeprod.excelsoftcorp.com/AIMarkingAPI/api';
      const response = await fetch(`${baseUrl}/get-config-info?OrgCode=${encodeURIComponent(orgCode)}&CustCode=${encodeURIComponent(custCode)}&AppCode=AImarking`, { cache: 'no-store' });
      if (response.ok) {
        const rawConfig = await response.json();
        let unwrappedConfig: any = null;
        if (rawConfig && Array.isArray(rawConfig.value) && rawConfig.value.length > 0) {
          unwrappedConfig = rawConfig.value[0].configSetting || rawConfig.value[0];
        } else if (rawConfig && Array.isArray(rawConfig.Data) && rawConfig.Data.length > 0) {
          unwrappedConfig = rawConfig.Data[0].configSetting || rawConfig.Data[0];
        } else if (Array.isArray(rawConfig) && rawConfig.length > 0) {
          unwrappedConfig = rawConfig[0].configSetting || rawConfig[0];
        } else if (rawConfig && rawConfig.configSetting) {
          unwrappedConfig = rawConfig.configSetting;
        } else if (rawConfig && typeof rawConfig === 'object') {
          unwrappedConfig = rawConfig;
        }

        if (unwrappedConfig && unwrappedConfig.workflowStages) {
          setApiConfig(unwrappedConfig);
          setWorkflowStages(unwrappedConfig.workflowStages);
          try {
            localStorage.setItem('workflowStages', JSON.stringify(unwrappedConfig.workflowStages));
          } catch (_) {}
          if (unwrappedConfig.standalone !== undefined) {
            setStandaloneMode(!!unwrappedConfig.standalone);
            try {
              localStorage.setItem('standalone_mode', unwrappedConfig.standalone ? '1' : '0');
            } catch (_) {}
          }
        } else if (unwrappedConfig) {
          setApiConfig(unwrappedConfig);
        } else {
          setIsConfigError(true);
        }
      } else {
        setIsConfigError(true);
      }
    } catch (e) {
      console.error("Failed to fetch apiConfig", e);
      setIsConfigError(true);
    } finally {
      setIsConfigLoading(false);
    }
  }, []);

  useEffect(() => {
    void fetchConfig();
  }, [fetchConfig, selectedWorkspace]);

