  const deleteWillEmptyWorkspace = candidates.length > 0
    && pendingDeleteCandidates.length >= candidates.length

  const rankEvalDataByMarksAwarded = React.useCallback((evalData: any) => {
    if (!evalData || typeof evalData !== 'object') return evalData

    const entries = Object.entries(evalData)
      .filter(([, v]) => v && typeof v === 'object')
      .map(([k, v]) => {
        const marksAwardedRaw = (v as any).marks_awarded
        const marksAwarded = Number(marksAwardedRaw)
        return {
          key: String(k),
          marks: Number.isFinite(marksAwarded) ? marksAwarded : 0,
        }
      })

    entries.sort((a, b) => {
      const diff = b.marks - a.marks
      if (diff !== 0) return diff
      return a.key.localeCompare(b.key)
    })

    const keyToRank: Record<string, number> = {}
    let rank = 1
    let lastMarks: number | null = null

    for (const e of entries) {
      if (lastMarks === null) {
        keyToRank[e.key] = rank
        lastMarks = e.marks
        continue
      }

      if (e.marks !== lastMarks) {
        rank += 1
        lastMarks = e.marks
      }

      keyToRank[e.key] = rank
    }

    const out: any = { ...evalData }
    for (const [k, v] of Object.entries(evalData)) {
      if (!v || typeof v !== 'object') continue
      const nextRank = keyToRank[String(k)]
      if (!nextRank) continue
      out[k] = { ...(v as any), rank: nextRank }
    }
    return out
  }, [])

  const computeObtainedScoreWithTopN = React.useCallback((evalData: any, topN?: number | string) => {
    let values = Object.values(evalData || {}).map((q: any) => {
      const marksAwarded = (q && typeof q === 'object' && 'marks_awarded' in q)
        ? Number(q.marks_awarded)
        : 0
      return Number.isFinite(marksAwarded) ? marksAwarded : 0
    })

    // Parse topN — accepts plain number or string like "4/8"
    let topNParsed = 0;
    if (typeof topN === 'number') {
      topNParsed = Number.isFinite(topN) ? topN : 0;
    } else if (typeof topN === 'string' && topN.trim()) {
      const parsed = parseInt(topN.split('/')[0], 10);
      topNParsed = isNaN(parsed) ? 0 : parsed;
    }

    if (topNParsed > 0) {
      values.sort((a, b) => b - a)
      values = values.slice(0, topNParsed)
    }

    return values.reduce((sum, val) => sum + val, 0)
  }, [])

  const saveFilteredEvaluationDataWithoutImagePaths = React.useCallback(async (params: {
    candidateForSave: CandidateData
    processDataOverride?: any
  }) => {
    const { candidateForSave, processDataOverride } = params

    const orgcode = sessionStorage.getItem('orgCode') || sessionStorage.getItem('orgcode') || 'ICME01'
    const custcode = 'ICME'
    const usercode = sessionStorage.getItem('userCode') || sessionStorage.getItem('usercode') || 'icmeuserone'
    const registrationnumber = (candidateForSave.registrationName && candidateForSave.registrationName.trim()) || String(candidateForSave.id || '')
    const subjectcode = resolveSubjectCode() || selectedSubject || 'S1'
    const workspaceidRaw = String(selectedWorkspace?.id || sessionStorage.getItem('workspaceid') || '')
    const workspaceid = /^\d+$/.test(workspaceidRaw) ? Number(workspaceidRaw) : (Number(workspaceidRaw) || 0)

    const procForSave = processDataOverride ?? evaluationProcessData
    if (!procForSave || typeof procForSave !== 'object') return

    const proc = procForSave
    const evalData = (proc as any).eval_data && typeof (proc as any).eval_data === 'object' ? (proc as any).eval_data : {}

    const questionPageMapping =
      phase1IndexingRecord?.question_page_mapping
      || (proc as any)?.question_page_mapping
      || (proc as any)?.questionPageMapping
      || {}

    const questionsWithImages = new Set(
      getQuestionNumbersWithImagePathsFromMapping(questionPageMapping).map((q) => String(q))
    )

    const parseQuestionNumber = (rawKey: string): number | null => {
      const trimmed = String(rawKey ?? '').trim()
      if (!trimmed) return null
      const direct = Number(trimmed)
      if (Number.isFinite(direct) && direct > 0) return direct
      const m = trimmed.match(/\d+/)
      if (!m) return null
      const parsed = Number(m[0])
      return Number.isFinite(parsed) && parsed > 0 ? parsed : null
    }

    const filteredEvalData = questionsWithImages.size > 0
      ? Object.fromEntries(
        Object.entries(evalData).filter(([k]) => {
          const qNum = parseQuestionNumber(k)
          return qNum != null && questionsWithImages.has(String(qNum))
        })
      )
      : evalData

    const rankedEvalData = rankEvalDataByMarksAwarded(filteredEvalData)
    const currentSubjectForConfig = candidateForSave?.subjectCode || subjectcode
    const subjectOverrides = apiConfig?.evaluationConfig?.subjectOverrides || []
    const override = subjectOverrides.find((s: any) => s.subjectCode === currentSubjectForConfig)
    let topQuestionsCount = apiConfig?.evaluationConfig?.globalThresholds?.topQuestionsCount
    if (override && override.topQuestionsCount) {
      topQuestionsCount = override.topQuestionsCount
    }
    const recomputedObtainedScore = computeObtainedScoreWithTopN(rankedEvalData, topQuestionsCount)

    const updatedProc: any = {
      ...proc,
      eval_data: rankedEvalData,
      final_score: {
        ...((proc as any).final_score || {}),
        obtained_score: recomputedObtainedScore,
      }
    }

    const buildQuestionDetails = (finalResult: any): Array<{ Qid: number; maxscore: number; obtainedscore: number; rank: number }> => {
      const arr: Array<{ Qid: number; maxscore: number; obtainedscore: number; rank: number }> = []
      const ranked: Record<string, any> = finalResult?.all_questions_ranked || finalResult?.eval_data || {}
      for (const [qid, qdata] of Object.entries(ranked)) {
        const q = qdata as any
        const direct = Number(String(qid).trim())
        const fromDigits = String(qid).match(/\d+/)
        const Qid = Number.isFinite(direct) && direct > 0 ? direct : (fromDigits ? Number(fromDigits[0]) : 0)
        if (!Number.isFinite(Qid) || Qid <= 0) continue
        const maxscore = Number(q?.marks_max ?? q?.marksMax ?? 0) || 0
        const obtainedscore = Number(q?.marks_awarded ?? q?.marksAwarded ?? 0) || 0
        const rank = Number(q?.rank ?? 0) || 0
        arr.push({ Qid, maxscore, obtainedscore, rank })
      }
      return arr
    }

    const evaluateddata: any = {
      ...updatedProc,
      registration_number: (updatedProc as any)?.registration_number ?? registrationnumber,
    }

    const finalMaxScore = Number((updatedProc as any)?.final_score?.max_score ?? 0) || 0

    const payload: any = {
      orgcode,
      custcode,
      obtainedscore: recomputedObtainedScore,
      evaluateddata,
      questiondetails: buildQuestionDetails(updatedProc),
      maxscore: finalMaxScore,
      registrationnumber,
      subjectcode,
      workspaceid,
    }

    return axios.post(API_ENDPOINTS.saveEvaluationData, sanitizePayload(payload))
  }, [evaluationProcessData, getQuestionNumbersWithImagePathsFromMapping, phase1IndexingRecord, rankEvalDataByMarksAwarded, resolveSubjectCode, selectedSubject, selectedWorkspace, apiConfig, computeObtainedScoreWithTopN])

  const saveEvaluationScoreOnServer = React.useCallback(async (params: {
    candidateForSave: CandidateData
    questionId: number | string
    maxScore: number
    obtainedScore: number
    newTotal?: number
    processDataOverride?: any
    manualMarking?: string
  }) => {
    const { candidateForSave, questionId, maxScore, obtainedScore, processDataOverride, manualMarking } = params

    const orgcode = sessionStorage.getItem('orgCode') || sessionStorage.getItem('orgcode') || 'ICME01'
    const custcode = 'ICME'
    const usercode = sessionStorage.getItem('userCode') || sessionStorage.getItem('usercode') || 'icmeuserone'
    const registrationnumber = (candidateForSave.registrationName && candidateForSave.registrationName.trim()) || String(candidateForSave.id || '')
    const subjectcode = resolveSubjectCode() || selectedSubject || 'S1'
    const workspaceidRaw = String(selectedWorkspace?.id || sessionStorage.getItem('workspaceid') || '')
    const workspaceid = /^\d+$/.test(workspaceidRaw) ? Number(workspaceidRaw) : (Number(workspaceidRaw) || 0)

    const procForSave = processDataOverride ?? evaluationProcessData
    if (!procForSave || typeof procForSave !== 'object') {
      throw new Error('Missing evaluation processdata (get-process-data type=3).')
    }

    // Build updated processdata with updated marks_awarded for the relevant question.
    const proc = procForSave
    const evalData = (proc as any).eval_data && typeof (proc as any).eval_data === 'object' ? (proc as any).eval_data : {}

    // Pick the key that exists in eval_data for this question.
    const questionKeyCandidates = [String(questionId).trim(), String(Number(questionId)).trim()].filter(Boolean)
    const existingKey = questionKeyCandidates.find(k => Object.prototype.hasOwnProperty.call(evalData, k))
      ?? Object.keys(evalData).find(k => String(k).trim() === String(questionId).trim())
      ?? String(questionId).trim()

    const existingEntry = (evalData as any)[existingKey] && typeof (evalData as any)[existingKey] === 'object'
      ? (evalData as any)[existingKey]
      : {}

    const updatedEvalData = {
      ...evalData,
      [existingKey]: {
        ...existingEntry,
        marks_awarded: obtainedScore,
        marks_max: existingEntry?.marks_max ?? maxScore,
        ...(manualMarking != null ? { manual_marking: manualMarking } : {}),
      }
    }

    // Keep only questions that currently have image paths mapped.
    // IMPORTANT: do not wipe eval_data when mapping is temporarily unavailable.
    const questionPageMapping =
      phase1IndexingRecord?.question_page_mapping
      || (proc as any)?.question_page_mapping
      || (proc as any)?.questionPageMapping
      || {}

    const questionsWithImagesList = getQuestionNumbersWithImagePathsFromMapping(questionPageMapping)
    const questionsWithImages = new Set(questionsWithImagesList.map((q) => String(q)))

    const parseQuestionNumber = (rawKey: string): number | null => {
      const trimmed = String(rawKey ?? '').trim()
      if (!trimmed) return null
      const direct = Number(trimmed)
      if (Number.isFinite(direct) && direct > 0) return direct
      const m = trimmed.match(/\d+/)
      if (!m) return null
      const parsed = Number(m[0])
      return Number.isFinite(parsed) && parsed > 0 ? parsed : null
    }

    const filteredUpdatedEvalData = questionsWithImages.size > 0
      ? Object.fromEntries(
        Object.entries(updatedEvalData).filter(([k]) => {
          const qNum = parseQuestionNumber(k)
          return qNum != null && questionsWithImages.has(String(qNum))
        })
      )
      : updatedEvalData

    const updatedEvalDataRanked = rankEvalDataByMarksAwarded(filteredUpdatedEvalData)

    const updatedProc: any = {
      ...proc,
      eval_data: updatedEvalDataRanked,
    }

    const currentSubjectForConfig = candidateForSave?.subjectCode || subjectcode
    const subjectOverrides = apiConfig?.evaluationConfig?.subjectOverrides || []
    const override = subjectOverrides.find((s: any) => s.subjectCode === currentSubjectForConfig)
    let topQuestionsCount = apiConfig?.evaluationConfig?.globalThresholds?.topQuestionsCount
    if (override && override.topQuestionsCount) {
      topQuestionsCount = override.topQuestionsCount
    }
    const recomputedObtainedScore = computeObtainedScoreWithTopN(updatedEvalDataRanked, topQuestionsCount)

    if (updatedProc.final_score && typeof updatedProc.final_score === 'object') {
      updatedProc.final_score = {
        ...updatedProc.final_score,
        obtained_score: recomputedObtainedScore,
      }
    }

    // Payload format as per save-evaluation-data API (Jan 2026):
    // evaluateddata should be the processdata object itself (eval_data/final_score/etc),
    // not wrapped under candidateid/processdata.
    const evaluateddata: any = {
      ...updatedProc,
      registration_number: (updatedProc as any)?.registration_number ?? registrationnumber,
    }

    // Build question details array expected by backend: [{ Qid, maxscore, obtainedscore, rank }, ...]
    const buildQuestionDetails = (finalResult: any): Array<{ Qid: number; maxscore: number; obtainedscore: number; rank: number }> => {
      const arr: Array<{ Qid: number; maxscore: number; obtainedscore: number; rank: number }> = []
      if (!finalResult || typeof finalResult !== 'object') return arr

      // Prefer `all_questions_ranked` if present, otherwise fall back to `eval_data`.
      const ranked: Record<string, any> = finalResult.all_questions_ranked || finalResult.eval_data || {}

      for (const [qid, qdata] of Object.entries(ranked)) {
        try {
          const q = qdata as any
          const direct = Number(String(qid).trim())
          const fromDigits = String(qid).match(/\d+/)
          const Qid = Number.isFinite(direct) && direct > 0
            ? direct
            : (fromDigits ? Number(fromDigits[0]) : 0)
          if (!Number.isFinite(Qid) || Qid <= 0) continue
          const maxscore = Number(q?.marks_max ?? q?.marksMax ?? 0) || 0
          const obtainedscore = Number(q?.marks_awarded ?? q?.marksAwarded ?? 0) || 0
          const rank = Number(q?.rank ?? 0) || 0
          arr.push({ Qid, maxscore, obtainedscore, rank })
        } catch {
          // ignore malformed entries
        }
      }

      return arr
    }

    // Prefer the overall obtained score from the processdata final_score if present
    const finalObtainedFromProc = (updatedProc && updatedProc.final_score && (updatedProc.final_score.obtained_score ?? updatedProc.final_score.obtainedScore))
    const payload: any = {
      orgcode,
      custcode,
      obtainedscore: typeof finalObtainedFromProc === 'number' && Number.isFinite(finalObtainedFromProc)
        ? Number(finalObtainedFromProc)
        : Number(recomputedObtainedScore),
      evaluateddata,
      // Extra parameter required by backend: include per-question details built from processdata.
      questiondetails: buildQuestionDetails(updatedProc),
      maxscore: maxScore,
      registrationnumber,
      subjectcode,
      workspaceid,
      manual_marking: manualMarking ?? '',
    }

    return axios.post(API_ENDPOINTS.saveEvaluationData, sanitizePayload(payload))
  }, [evaluationProcessData, getQuestionNumbersWithImagePathsFromMapping, phase1IndexingRecord, rankEvalDataByMarksAwarded, resolveSubjectCode, selectedSubject, selectedWorkspace, apiConfig, computeObtainedScoreWithTopN])
  // Evaluation info center dialog state
  const [showEvalInfoDialog, setShowEvalInfoDialog] = useState(false)
  // Standards met details dialog state
  const [standardsDialogCandidate, setStandardsDialogCandidate] = useState<CandidateData | null>(null)

  const confirmDeleteSelectedCandidates = React.useCallback(async () => {
    const selectedObjs = pendingDeleteCandidates
    if (!selectedObjs || selectedObjs.length === 0) {
      setShowDeleteConfirmDialog(false)
      return
    }

    // Deletable only when marking status === 2 (marking completed)
    // and not when any phase status equals 3 (phase-3 -> download-only)
    // Regular users can delete, but superadmin cannot
    if (isSuperAdmin) {
      toast.error('Superadmin cannot delete candidates')
      setShowDeleteConfirmDialog(false)
      setPendingDeleteCandidates([])
      return
    }



    const orgcode = sessionStorage.getItem('orgCode') || sessionStorage.getItem('orgcode') || 'ICME01'
    const custcode = 'ICME'
    const usercode = sessionStorage.getItem('userCode') || sessionStorage.getItem('usercode') || 'icmeuer01'
    const workspaceidRaw = String(selectedWorkspace?.id || sessionStorage.getItem('workspaceid') || '')
    const workspaceid = workspaceidRaw
    const subject_id = resolveSubjectCode() || selectedSubject || ''

    setIsDeletingCandidates(true)
    try {
      const registrationNumbers = selectedObjs
        .map(cand => (cand.registrationName && cand.registrationName.trim()) || String(cand.id))
        .join(',')

      const payload = { orgcode, custcode, usercode, workspaceid, subject_id, registrationnumber: registrationNumbers }

      try {
        const res = await axios.post(API_ENDPOINTS.deleteCandidate, payload)
        if (res && res.data && (res.data.success || res.status === 200)) {
          const remaining = candidates.filter(c => !selectedObjs.some(s => String(s.id) === String(c.id)))
          setCandidates(remaining)
          toast.success(`Successfully deleted`)

          // The last candidates are gone, so the workspace that held them is
          // removed too rather than left behind empty.
          if (remaining.length === 0 && selectedWorkspace) {
            const workspaceName = selectedWorkspace.name
            try {
              const wsRes = await axios.post(API_ENDPOINTS.deleteWorkspace, { workspaceId: String(selectedWorkspace.id) })
              const wsData = wsRes && wsRes.data ? wsRes.data : null
              const deleted = wsData && (wsData.status === 'S001' || wsData.responseCode === 'S001'
                || wsData.ResponseCode === 'S001' || wsData.status === 'success')
              if (deleted) {
                toast.success(wsData?.message || `Workspace "${workspaceName}" deleted`)
                stopCandidatePolling()
                setSelectedWorkspace(null)
                setHasUploaded(false)
                await refreshWorkspacesRef.current({ silent: true, force: true })
              } else {
                toast.error(wsData?.message || `Candidates deleted, but workspace "${workspaceName}" could not be removed.`)
              }
            } catch (wsErr) {
              console.error('Failed to delete the emptied workspace', wsErr)
              toast.error(`Candidates deleted, but workspace "${workspaceName}" could not be removed.`)
            }
          } else if (selectedWorkspace) {
            // Still has candidates: just keep its count in step.
            const newCandidateCount = Math.max(0, (selectedWorkspace.candidateCount || 0) - selectedObjs.length)
            const updatedWorkspace = { ...selectedWorkspace, candidateCount: newCandidateCount }
            setSelectedWorkspace(updatedWorkspace)
            setWorkspaces(prev => prev.map(w => w.id === selectedWorkspace.id ? updatedWorkspace : w))
          }
        } else {
          console.error('Failed to delete candidates', res?.data || res)
          toast.error(`Failed to delete candidates`)
        }
      } catch (err) {
        console.error('Failed to delete candidates', err)
        toast.error(`Failed to delete candidates`)
      }

      // Clear selection after delete attempt
      setSelectedCandidates(new Set())
    } finally {
      setIsDeletingCandidates(false)
      setShowDeleteConfirmDialog(false)
      setPendingDeleteCandidates([])
    }
    // candidates is read to decide whether the workspace is now empty, so a stale
    // copy here would delete a workspace that still has rows (or keep an empty one).
  }, [pendingDeleteCandidates, candidates, stopCandidatePolling, resolveSubjectCode, selectedSubject, selectedWorkspace])

  // Manual marking is allowed only when the candidate's Quick Approve is enabled.
  React.useEffect(() => {
    if (!evaluationReviewCandidate) return
    if (!evaluationReviewCandidate.quickApprove) {
      setManualMarkingEnabled(false)
      setPendingScoresMap({})
      setPendingSubScoresMap({})
      setManualMarkingErrors({})
      setActiveManualMarkingInputKey(null)
    }
  }, [evaluationReviewCandidate])

  // Ensure the Segmentation Indexing dialog always starts from the first question.
  // Some open paths can set `phase1ReviewCandidate` without going through
  // `handleOpenPhase1Review`, which can leave a previous `activeQuestionIndex` in place.
  // That makes it look like users can jump to any question when quickApprove (Approve button)
  // is not shown.
  React.useEffect(() => {
    if (!phase1ReviewCandidate) return

    setPhase1ViewMode('question')
    setFromPageInput("")
    setToPageInput("")
    setRepositionSelections([''])
    setActiveQuestionIndex(0)
    setPhase1VisitedQuestions(new Set([0]))
    setActiveAnswerSheetIndex(0)
    setZoomLevel(50)
    setPhase1ImageLoadError(false)
  }, [phase1ReviewCandidate])

  // When the active evaluation question changes, collapse sub-question details by default
  // (Implementation moved below after `questions` is declared to avoid use-before-declare errors.)

  // If the currently active answer-sheet refers to a local Windows/UNC path or a file:// URL,
  // the browser will block access. Proactively set `phase1ImageLoadError` so the UI shows
  // the guidance message (instead of waiting for the img onError callback).
  React.useEffect(() => {
    const current = (answerSheets && answerSheets[activeAnswerSheetIndex]) as AnswerSheetPage | undefined
    if (!current) {
      setPhase1ImageLoadError(false)
      return
    }
    const raw = String(current.sourcePath ?? current.imageUrl ?? '')
    const looksLikeWindowsAbs = /^[a-zA-Z]:\\\\/.test(raw)
    const looksLikeUNC = /^\\\\/.test(raw)
    const isFileUrl = String(current.imageUrl ?? '').startsWith('file://')
    setPhase1ImageLoadError(looksLikeWindowsAbs || looksLikeUNC || isFileUrl)
  }, [answerSheets, activeAnswerSheetIndex])

  const [subjects, setSubjects] = useState<{ value: string; label: string; id?: string | number; code?: string; guidelinepath?: string }[]>([
    { value: "broadcast-journalism", label: "Workspaces", id: "broadcast-journalism", code: "broadcast-journalism" },
    { value: "print-journalism", label: "Print Journalism", id: "print-journalism", code: "print-journalism" },
    { value: "digital-media", label: "Digital Media", id: "digital-media", code: "digital-media" },
    { value: "mass-communication", label: "Mass Communication", id: "mass-communication", code: "mass-communication" },
    { value: "public-relations", label: "Public Relations", id: "public-relations", code: "public-relations" },
    { value: "advertising", label: "Advertising", id: "advertising", code: "advertising" },
    { value: "media-studies", label: "Media Studies", id: "media-studies", code: "media-studies" },
    { value: "film-production", label: "Film Production", id: "film-production", code: "film-production" },
  ])

  // Determine if Question Number Extraction is enabled based on API config (fallback to localStorage)
  const isQNumExtractionEnabled = React.useMemo(() => {
    // 1. API Configuration takes precedence
    if (apiConfig?.ocrConfig?.QuestionNumberExtraction !== undefined) {
      return apiConfig.ocrConfig.QuestionNumberExtraction === true;
    }
    // 2. Fallback to localStorage overrides
    const orgCode = sessionStorage.getItem('orgCode') || 'ICMELIVE'
    const subjCode = resolveSubjectCode() || selectedSubject || '1'
    const subjKey = `org_ocr_qnum_${orgCode}_${subjCode}`
    if (localStorage.getItem(subjKey) !== null) {
      return localStorage.getItem(subjKey) === '1'
    }
    const globalKey = `org_ocr_qnum_${orgCode}`
    return localStorage.getItem(globalKey) === '1'
  }, [resolveSubjectCode, selectedSubject, apiConfig])

  // Shared by every subject fetch below (initial load, refresh, and the
  // Subject dropdown's own re-fetch) so the mapping only lives in one place.
  const mapSubjectApiItems = React.useCallback((arr: any[]) => arr.filter((item: any) => {
    if (typeof item === 'object' && item !== null && 'status' in item) {
      return item.status === 1;
    }
    return true; // For string items or items without status, keep them by default
  }).map((item: any) => {
    if (typeof item === 'string') {
      const v = item.toLowerCase().replace(/\s+/g, '-')
      return { value: v, label: item, id: v, code: v }
    }
    const label = item.subjectname || item.subjectName || item.SName || item.label || item.name || item.subject || item.displayName || item.description || String(item)
    const value = item.subjectcode || item.subjectCode || item.value || item.code || item.id || (typeof label === 'string' ? label.toLowerCase().replace(/\s+/g, '-') : String(Math.random()))
    const id = item.subjectid || item.subjectId || item.id || value
    const code = item.subjectcode || item.subjectCode || item.code || value
    const guidelinepath = item.guidelinepath || item.guidelinePath || null
    return { value: String(value), label: String(label), id: id, code: String(code), guidelinepath }
  }), [])

  // Single get-subject-data call for one known Year + Cycle - the fast path,
  // used whenever the Home page has already told us which pair the user
  // picked (see fetchSubjectsSmart below).
  const fetchSubjectsForYearCycle = React.useCallback(async (yearCode: string, cycleCode: string): Promise<any[]> => {
    const { orgCode, custCode, userCode } = getFinalCodes()
    const res = await axios.get(API_ENDPOINTS.subjectData, {
      params: { orgCode, custCode, yearCode, cycleCode, userCode },
      headers: { 'Cache-Control': 'no-cache', 'Pragma': 'no-cache', 'Expires': '0' },
    })
    const data = res?.data
    return Array.isArray(data) ? data : (Array.isArray(data?.data) ? data.data : [])
  }, [getFinalCodes])

  // get-subject-data only ever answers for one Year + Cycle, unlike the old
  // org-wide subject-list this dropdown used to read from. Fallback path for
  // when no Year/Cycle was handed off (e.g. arriving here some other way than
  // picking a subject on the Home page): fans out across every Year x Cycle
  // combination and merges the results, de-duped by subject code. That is a
  // lot more requests than a single call, so fetchSubjectsSmart below only
  // reaches for this when it has to.
  const fetchAllSubjectsAcrossYearsAndCycles = React.useCallback(async (): Promise<any[]> => {
    const yearRes = await axios.get(API_ENDPOINTS.yearData)
    const yearData = yearRes?.data
    const years: any[] = Array.isArray(yearData) ? yearData : (Array.isArray(yearData?.data) ? yearData.data : [])
    const yearCodes = Array.from(new Set(
      years
        .map((y: any) => (y && (y.yearcode ?? y.yearCode)) ? String(y.yearcode ?? y.yearCode) : '')
        .filter(Boolean)
    ))

    const perYearCycles = await Promise.all(yearCodes.map(async (yearCode) => {
      try {
        // OrgCode scopes the cycles to the signed-in organization; it comes from
        // the login response the session holds.
        const { orgcode } = getSessionCodes()
        const cycleRes = await axios.get(API_ENDPOINTS.cycleData, {
          params: {
            YearCode: yearCode,
            OrgCode: (orgcode || sessionStorage.getItem('orgCode') || '').replace(/\x00/g, ''),
          },
        })
        const cycleData = cycleRes?.data
        const cycles: any[] = Array.isArray(cycleData) ? cycleData : (Array.isArray(cycleData?.data) ? cycleData.data : [])
        const cycleCodes = Array.from(new Set(
          cycles
            .map((c: any) => (c && (c.cyclecode ?? c.cycleCode)) ? String(c.cyclecode ?? c.cycleCode) : '')
            .filter(Boolean)
        ))
        return cycleCodes.map(cycleCode => ({ yearCode, cycleCode }))
      } catch (e) {
        console.error(`Failed to load cycles for year ${yearCode}`, e)
        return []
      }
    }))
    const yearCyclePairs = perYearCycles.flat()

    const { orgCode, custCode, userCode } = getFinalCodes()
    const perPairSubjects = await Promise.all(yearCyclePairs.map(async ({ yearCode, cycleCode }) => {
      try {
        const res = await axios.get(API_ENDPOINTS.subjectData, {
          params: { orgCode, custCode, yearCode, cycleCode, userCode },
          headers: { 'Cache-Control': 'no-cache', 'Pragma': 'no-cache', 'Expires': '0' },
        })
        const data = res?.data
        return Array.isArray(data) ? data : (Array.isArray(data?.data) ? data.data : [])
      } catch (e) {
        console.error(`Failed to load subjects for ${yearCode}/${cycleCode}`, e)
        return []
      }
    }))

    // De-dupe by subject code (case-insensitive) so a subject present in
    // several cycles appears once, keeping the first copy seen.
    const seen = new Set<string>()
    const merged: any[] = []
    for (const item of perPairSubjects.flat()) {
      const code = String(item?.subjectcode ?? item?.subjectCode ?? '').trim().toLowerCase()
      const key = code || JSON.stringify(item)
      if (seen.has(key)) continue
      seen.add(key)
      merged.push(item)
    }
    return merged
  }, [getFinalCodes])

  // The dropdown's actual entry point: use the Year/Cycle the Home page
  // already resolved and stored (fast, single call) when it's there, and
  // only fall back to rebuilding the full list across every Year x Cycle
  // when arriving here without one.
  const fetchSubjectsSmart = React.useCallback(async (): Promise<any[]> => {
    const yearCode = sessionStorage.getItem('yearcode') || sessionStorage.getItem('yearCode') || ''
    const cycleCode = sessionStorage.getItem('cyclecode') || sessionStorage.getItem('cycleCode') || ''
    if (yearCode && cycleCode) {
      try {
        return await fetchSubjectsForYearCycle(yearCode, cycleCode)
      } catch (e) {
        console.error(`Failed to load subjects for known year/cycle ${yearCode}/${cycleCode}`, e)
        // Fall through to the full fan-out below rather than leaving the
        // dropdown empty over one bad call.
      }
    }
    return fetchAllSubjectsAcrossYearsAndCycles()
  }, [fetchSubjectsForYearCycle, fetchAllSubjectsAcrossYearsAndCycles])

  useEffect(() => {
    let mounted = true
    const fetchSubjects = async () => {
      try {
        const data: any = await fetchSubjectsSmart()

        let mapped: { value: string; label: string }[] = []
        if (Array.isArray(data)) {
          mapped = mapSubjectApiItems(data)
        } else if (data && typeof data === 'object') {
          const arr = data.subjects || data.data || data.items || []
          if (Array.isArray(arr) && arr.length > 0) mapped = mapSubjectApiItems(arr)
        }

        if (mounted && mapped.length > 0) {
          setSubjects(mapped)
          const matched = mapped.some(s => s.value === selectedSubject)
            ? selectedSubject
            : mapped[0].value
          setSelectedSubject(matched)
          const fullData = mapped.find(s => s.value === (matched || selectedSubject))
          setActiveSubjectData(fullData || null)
          // toast suppressed: 'Subjects loaded' removed per request
        }
      } catch (err) {
        console.error('Failed to fetch subjects', err)
        toast.error('Failed to load subjects')
      } finally {
        if (mounted) setSubjectsLoaded(true)
      }
    }

    fetchSubjects()
    return () => { mounted = false }
  }, [fetchSubjectsSmart, mapSubjectApiItems])

  // Refresh subjects function for updating subject list
  const refreshSubjects = React.useCallback(async () => {
    try {
      const data: any = await fetchSubjectsSmart()

      let mapped: { value: string; label: string }[] = []
      if (Array.isArray(data)) {
        mapped = mapSubjectApiItems(data)
      } else if (data && typeof data === 'object') {
        const arr = data.subjects || data.data || data.items || []
        if (Array.isArray(arr) && arr.length > 0) mapped = mapSubjectApiItems(arr)
      }

      if (mapped.length > 0) {
        setSubjects(mapped)
        const matched = mapped.some(s => s.value === selectedSubject)
          ? selectedSubject
          : mapped[0].value
        setSelectedSubject(matched)
        const fullData = mapped.find(s => s.value === (matched || selectedSubject))
        setActiveSubjectData(fullData || null)
      }
    } catch (err) {
      console.error('Failed to refresh subjects', err)
    }
  }, [selectedSubject, fetchSubjectsSmart, mapSubjectApiItems])

  const listWorkspaceMountedRef = React.useRef(true)
  const listWorkspaceInFlightRef = React.useRef(false)
  const listWorkspaceLastKeyRef = React.useRef<string | null>(null)
  const listWorkspaceLastAtRef = React.useRef<number>(0)
  const listWorkspaceAbortRef = React.useRef<AbortController | null>(null)
  const [isRefreshingWorkspaces, setIsRefreshingWorkspaces] = useState(false)

  React.useEffect(() => {
    listWorkspaceMountedRef.current = true
    return () => {
      listWorkspaceMountedRef.current = false
    }
  }, [])

  // Returns the freshly-fetched list (or null when this call didn't actually
  // fetch, e.g. it bailed out behind another in-flight request) so a caller
  // that needs the current data right after refreshing doesn't have to read
  // the `workspaces` state closure, which won't reflect this call's result
  // until the next render.
  const refreshWorkspaces = React.useCallback(async (options?: { silent?: boolean; force?: boolean }): Promise<Workspace[] | null> => {
    const silent = options?.silent === true
    const force = options?.force === true

    // Show page loader during non-silent refreshes (e.g. subject changes)
    if (!silent) setWorkspacesLoaded(false)

    const today = new Date()
    const todate = today.toISOString().slice(0, 10) // YYYY-MM-DD
    const defaultFrom = '2024-12-01' // default from date as requested (1/12/24)

    const sessionCode = sessionStorage.getItem('subjectcode') || sessionStorage.getItem('subjectCode') || sessionStorage.getItem('subject_code') || sessionStorage.getItem('subject') || null
    const sessionId = sessionStorage.getItem('subjectid') || sessionStorage.getItem('subjectId') || sessionStorage.getItem('subject_id') || null
    const matched = subjects.find(s => s.value === selectedSubject)
    const fromMatchedCode = matched?.code ?? null
    const fromMatchedValue = matched?.value ?? null
    const fromMatchedId = matched?.id ?? null
    const dynamicSubjectCode = (sessionCode || fromMatchedCode || fromMatchedValue || sessionId || fromMatchedId || selectedSubject || '').toString()
    // When standalone mode is ON, always use 'generic' as the subject code (matches create-workspace)
    const isStandaloneModeOn = localStorage.getItem('standalone_mode') === '1'
    const subjectCode = isStandaloneModeOn ? 'generic' : dynamicSubjectCode

    const { orgCode, custCode, userCode } = getFinalCodes()
    const payload = {
      fromdate: sessionStorage.getItem('fromdate') || defaultFrom,
      todate: sessionStorage.getItem('todate') || todate,
      orgcode: orgCode,
      custcode: custCode,
      usercode: userCode,
      SubjectCode: subjectCode,
    }

    const requestKey = `${payload.orgcode}|${payload.custcode}|${payload.usercode}|${payload.fromdate}|${payload.todate}|${payload.SubjectCode}`
    const now = Date.now()

    // Both guards below return before the try/finally that clears the loading
    // flag, so a non-silent call must put it back itself. Deleting the last
    // workspace hit this: the refresh that follows the delete collided with the
    // one the list view triggers, bailed out here, and left the page loader on
    // with nothing left to switch it off.
    const releaseLoadingFlag = () => { if (!silent) setWorkspacesLoaded(true) }

    // Hard guard: never run concurrent list-workspace requests. The request in
    // flight finishes and reports for both callers.
    if (listWorkspaceInFlightRef.current) {
      releaseLoadingFlag()
      return null
    }

    // Soft guard: ignore duplicate triggers for the same key in a short window.
    if (!force && listWorkspaceLastKeyRef.current === requestKey && (now - listWorkspaceLastAtRef.current) < 1500) {
      releaseLoadingFlag()
      return null
    }

    listWorkspaceInFlightRef.current = true
    listWorkspaceLastKeyRef.current = requestKey
    listWorkspaceLastAtRef.current = now
    setIsRefreshingWorkspaces(true)

    try {
      const windowMs = 1500
      const canShare = !force && sharedListWorkspaceRequest?.key === requestKey && (now - (sharedListWorkspaceRequest?.startedAt ?? 0)) < windowMs
      const isOwner = !canShare

      let listPromise: Promise<any[]>
      if (canShare && sharedListWorkspaceRequest) {
        listPromise = sharedListWorkspaceRequest.promise
      } else {
        const url = API_ENDPOINTS.listWorkspace
        listPromise = axios.get(url, { params: payload }).then((res) => {
          const data = res && res.data ? res.data : null
          let items: any[] = []
          if (Array.isArray(data)) items = data
          else if (Array.isArray((data as any)?.data)) items = (data as any).data
          else if (Array.isArray((data as any)?.workspaces)) items = (data as any).workspaces
          return items
        })

        sharedListWorkspaceRequest = { key: requestKey, startedAt: now, promise: listPromise }
      }

      const items = await listPromise

      if (!listWorkspaceMountedRef.current) return null

      if (items.length > 0) {
        const getCreatedMs = (it: any): number => {
          const raw = it?.createddate || it?.createdDate || it?.created_date || it?.createdAt || it?.date || ''
          const ms = raw ? Date.parse(String(raw)) : NaN
          return Number.isFinite(ms) ? ms : 0
        }

        const sortedItems = [...items].sort((a, b) => getCreatedMs(b) - getCreatedMs(a))

        const mapped: Workspace[] = sortedItems.map((it: any, idx: number) => {
          const statusNumeric = typeof it.status === 'number' ? it.status : (parseInt(it.status) || 0)
          const statusStr: Workspace['status'] = statusNumeric === 0 ? 'active' : statusNumeric === 1 ? 'completed' : 'archived'
          const createdAtRaw = it.createddate || it.createdDate || it.created_date || it.createdAt || it.date || ''
          const createdAt = createdAtRaw ? (new Date(createdAtRaw).toISOString().split('T')[0]) : ''

          return {
            id: String(it.workspaceid || it.workspace_id || it.id || it.workspaceId || it.workspaceID || `ws-${idx}`),
            name: String(it.workspacename || it.workspace_name || it.name || it.workspaceName || `Workspace ${idx + 1}`),
            createdAt,
            fileCount: Number(it.filecount || it.fileCount || it.files || 0),
            totalSize: Number(it.totalsize || it.totalSize || it.size || 0),
            candidateCount: Number(it.candidatecount || it.candidateCount || it.candidates || 0),
            // 1 marks an audio workspace; the card and the additional upload follow it.
            standardCount: Number(it.standardcount ?? it.standardCount ?? 0),
            totalTokenUsage: Number(it.totaltokenusage || it.totalTokenUsage || it.totaltoken || 0),
            userCode: String(it.usercode || it.userCode || it.UserCode || it.user_code || it.Usercode || it.createdby || it.createdBy || ''),
            status: statusStr,
          }
        })

        setWorkspaces(mapped)
        setQuestionsEmpty(false)
        // toast suppressed: 'Workspaces loaded' removed per request
        return mapped
      } else {
        setWorkspaces([])
        // If no workspaces, check for questions
        try {
          const qUrl = API_ENDPOINTS.questionList
          const qRes = await axios.get(qUrl, { params: { OrgCode: payload.orgcode, CustCode: payload.custcode, SubjectCode: payload.SubjectCode } })
          const qData = qRes && qRes.data ? qRes.data : null
          const qArr = Array.isArray(qData) ? qData : (Array.isArray(qData?.ref1Data) ? qData.ref1Data : [])
          if (listWorkspaceMountedRef.current) setQuestionsEmpty(qArr.length === 0)
        } catch (qErr) {
          console.warn('Failed to fetch questions for validation', qErr)
          if (listWorkspaceMountedRef.current) setQuestionsEmpty(false) // Default to false on error to avoid blocking if API fails
        }
        return []
      }
    } catch (err: any) {
      // Ignore abort errors.
      const aborted = err?.name === 'CanceledError' || err?.name === 'AbortError'
      if (!aborted) {
        console.error('Failed to fetch workspaces', err)
        if (!silent) toast.error('Failed to load workspaces')
      }
      return null
    } finally {
      if (listWorkspaceMountedRef.current) {
        setWorkspacesLoaded(true)
        setIsRefreshingWorkspaces(false)
      }
      listWorkspaceInFlightRef.current = false
    }
  }, [selectedSubject, subjects])

  // Fetch workspaces from ICME_OCR API.
  // Important: wait until subjects are loaded so we don't call list-workspace twice
  // (once for the default subject, then again after subject-list populates).
  const refreshWorkspacesRef = React.useRef(refreshWorkspaces)
  React.useEffect(() => {
    refreshWorkspacesRef.current = refreshWorkspaces
  }, [refreshWorkspaces])

  React.useEffect(() => {
    if (!subjectsLoaded) return
    if (!selectedSubject) {
      // Avoid a permanent page loader when subject list returns no usable value.
      setWorkspacesLoaded(true)
      return
    }
    void refreshWorkspacesRef.current()
  }, [subjectsLoaded, selectedSubject])

  // Derive page-level loading from initial subject + workspace fetches
  useEffect(() => {
    if (subjectsLoaded && (workspacesLoaded || !selectedSubject)) {
      setPageLoading(false)
    } else {
      setPageLoading(true)
    }
  }, [selectedSubject, subjectsLoaded, workspacesLoaded])

  const backToWorkspaceListInFlightRef = React.useRef(false)
  // Back to the subject dashboard: refreshes the subject list first so the counts
  // there are current, exactly as the old Back to Home button did.
  const goBackToHome = async () => {
    if (!onBack) return
    setPageLoading(true)
    try {
      // get-subject-data, via the same Year/Cycle-aware helper the Subject
      // dropdown uses, replacing the old org-wide subject-list call.
      await refreshSubjects()
    } catch (e) {
      console.error('Failed to refresh subject list', e)
    } finally {
      setPageLoading(false)
      onBack()
    }
  }

  // Back further still, to the Home page's Cycle picker - one level up from
  // goBackToHome, which only returns to this Cycle's subject list.
  const goBackToCycles = () => {
    if (!onBackToCycles) return
    onBackToCycles()
  }

  const handleBackToWorkspaceList = React.useCallback(async () => {
    if (backToWorkspaceListInFlightRef.current) return
    backToWorkspaceListInFlightRef.current = true
    setPageLoading(true)
    try {
      stopCandidatePolling()
      setSelectedWorkspace(null)
      setHasUploaded(false)
      setCandidates([])

      // Explicitly refresh the workspace list when returning to the list view.
      await refreshWorkspaces({ silent: true, force: true })
    } finally {
      setPageLoading(false)
      backToWorkspaceListInFlightRef.current = false
    }
  }, [refreshWorkspaces, stopCandidatePolling])

  // Unified breadcrumb: Year > Cycle > Subject > Workspace. Built as a plain
  // array of crumbs so both places that render it (workspace list, inside a
  // workspace) share the exact same "how do I get back to X" logic rather
  // than keeping two hand-nested breadcrumbs in sync.
  type BreadcrumbCrumb = { key: string; label: string; icon?: React.ReactNode; onClick?: () => void; disabled?: boolean }
  const buildBaseCrumbs = (): BreadcrumbCrumb[] => {
    if (!onBack) return []
    if (onBackToCycles) {
      const crumbs: BreadcrumbCrumb[] = []
      if (preselectedYearName) {
        crumbs.push({ key: 'year', label: preselectedYearName, icon: <Calendar className="w-4 h-4" aria-hidden="true" />, onClick: goBackToCycles })
      }
      // Same clickable behavior as the Year crumb above. In genericSubjectMode,
      // SubjectDashboard already wires this page's `onBack` to the same cycle
      // picker `onBackToCycles` goes to (see SubjectDashboard's
      // `onBack={isGenericSelection ? backToCycles : ...}`), so goBackToHome()
      // lands in the right place here too - there is no separate subject list
      // this needs to skip.
      if (preselectedCycleName) {
        crumbs.push({
          key: 'cycle',
          label: preselectedCycleName,
          onClick: () => void goBackToHome(),
        })
      }
      return crumbs
    }
    // No Year/Cycle was handed off - fall back to the plain Home crumb this
    // page used before Home had its own Cycle picker.
    return [{ key: 'home', label: 'Home', icon: <Home className="w-4 h-4" aria-hidden="true" />, onClick: () => void goBackToHome() }]
  }
  // Without a subject step there is no subject to name: the crumb that would
  // carry it reads "Workspaces", which is also where clicking it goes.
  const currentSubjectLabel = genericSubjectMode
    ? 'Workspaces'
    : subjects.find(s => s.value === selectedSubject)?.label || selectedSubjectLabel || 'Workspaces'
  const renderBreadcrumbNav = (crumbs: BreadcrumbCrumb[], leafLabel: string) => (
    <nav aria-label="Breadcrumb" className="flex items-center gap-1.5 text-sm text-slate-500 flex-wrap">
      {crumbs.map((crumb) => (
        // A plain span with display:contents groups these two nodes as direct flex
        // items of the nav, like a Fragment would, but - unlike React.Fragment -
        // it's a real DOM element that can carry the dev tooling's injected
        // data-lov-id attribute without the "Invalid prop" warning.
        <span key={crumb.key} className="contents">
          {crumb.onClick ? (
            <button
              type="button"
              onClick={crumb.onClick}
              disabled={crumb.disabled}
              className="inline-flex items-center gap-1.5 rounded-md px-1.5 py-0.5 hover:text-teal-700 hover:bg-teal-50 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {crumb.icon}
              {crumb.label}
            </button>
          ) : (
            <span className="inline-flex items-center gap-1.5">{crumb.icon}{crumb.label}</span>
          )}
          <ChevronRight className="w-4 h-4 text-slate-300 shrink-0" aria-hidden="true" />
        </span>
      ))}
      <span className="font-medium text-slate-800 truncate max-w-[16rem]" aria-current="page" title={leafLabel}>
        {leafLabel}
      </span>
    </nav>
  )

  const formatFileSize = (bytes: number): string => {
    if (bytes === 0) return '0 B'
    const k = 1024
    const sizes = ['B', 'KB', 'MB', 'GB']
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
  }

  /**
   * Config Settings asks for Max Questions on a flexible answer script, so the
   * fallback list is that long. Ten when the configuration carries no value.
   */
  const flexibleQuestionCount = (() => {
    const configured = Number(apiConfig?.indexingConfig?.flexibleSettings?.maxQuestions)
    return Number.isFinite(configured) && configured > 0 ? configured : PREDEFINED_QUESTION_COUNT
  })()

  // Shown when question-data has nothing for the subject, or could not be reached:
  // a list of numbered questions, the same shape Standalone Mode builds, so the
  // review always has questions to hang pages off instead of another subject's
  // sample text.
  const defaultQuestionList = Array.from({ length: flexibleQuestionCount }, (_, index) => ({
    id: index + 1,
    text: `Question ${index + 1}`,
    maxScore: 0,
    pages: 1,
    parts: [] as { text: string; marks?: number | null }[],
  }))

  // Questions loaded from ICME_OCR/question-list for the selected subject
  const [questions, setQuestions] = useState<{
    id: number | string
    text: string
    maxScore: number
    pages?: number
    parts?: { text: string; marks?: number | null; rubric?: { text: string; score: number }[] }[]
  }[]>(defaultQuestionList)

  /**
   * Standalone Mode has no subject, so the question list cannot come from the
   * question bank. It is built from the configured Max Questions instead, and
   * falls back to ten when the configuration carries no value. Standalone always
   * runs a flexible answer script, so its own Max Questions comes first; the
   * predefined value is still read so configurations saved before that field
   * existed keep working.
   */
  const standaloneQuestionCount = (() => {
    const flexible = Number(apiConfig?.indexingConfig?.flexibleSettings?.maxQuestions)
    if (Number.isFinite(flexible) && flexible > 0) return flexible
    const configured = Number(apiConfig?.indexingConfig?.predefinedSettings?.maxQuestions)
    return Number.isFinite(configured) && configured > 0 ? configured : PREDEFINED_QUESTION_COUNT
  })()

  useEffect(() => {
    if (!standaloneMode) return
    setQuestions(prev => {
      const alreadyBuilt = prev.length === standaloneQuestionCount
        && prev.every((question, index) => Number(question.id) === index + 1)
      if (alreadyBuilt) return prev
      return Array.from({ length: standaloneQuestionCount }, (_, index) => ({
        id: index + 1,
        text: `Question ${index + 1}`,
        maxScore: 0,
        pages: 1,
        parts: [],
      }))
    })
    // questions.length is watched too: the subject fetch can replace the list with
    // its own fallback, and standalone must end up with the configured count.
  }, [standaloneMode, standaloneQuestionCount, questions.length])

  // When the active evaluation question changes, collapse sub-question details by default
  React.useEffect(() => {
    // Reset manual-marking UI state
    setManualMarkingErrors({})
    setActiveManualMarkingInputKey(null)

    // By default collapse sub-questions. However, when manual marking is
    // enabled and the active question contains a sub-question breakdown
    // (`subquestion_evaluations`), auto-expand to make manual entry easier.
    try {
      let shouldOpen = false
      if (manualMarkingEnabled && evaluationDataMap && typeof evaluationDataMap === 'object') {
        const qIndexNumber = Number(evalActiveQuestionIndex) + 1
        // Direct key checks: index as string or `Q{index}`
        const directKeys = [String(qIndexNumber), `Q${qIndexNumber}`]
        for (const k of directKeys) {
          const entry = (evaluationDataMap as any)[k]
          const subMap = entry && typeof entry === 'object' ? entry.subquestion_evaluations : null
          if (subMap && typeof subMap === 'object' && Object.keys(subMap).length > 0) {
            shouldOpen = true
            break
          }
        }

        // Fallback: scan values for an embedded entry matching this question index
        if (!shouldOpen) {
          for (const v of Object.values(evaluationDataMap)) {
            if (!v || typeof v !== 'object') continue
            const subMap = (v as any).subquestion_evaluations
            if (subMap && typeof subMap === 'object' && Object.keys(subMap).length > 0) {
              // If the entry includes an embedded question id, try to match it to current index
              const embedded = (v as any).Qid ?? (v as any).qid ?? (v as any).question_id ?? (v as any).questionId ?? (v as any).questionid
              const embeddedNum = Number(String(embedded ?? ''))
              if (!Number.isNaN(embeddedNum) && embeddedNum === qIndexNumber) {
                shouldOpen = true
                break
              }
            }
          }
        }
      }
      setEvalSubQuestionsOpen(Boolean(shouldOpen))
    } catch (e) {
      setEvalSubQuestionsOpen(false)
    }
  }, [evalActiveQuestionIndex, evaluationReviewCandidate?.id, manualMarkingEnabled, evaluationDataMap, questions])

  // Mock evaluation data
  const generateMockEvaluationData = (): EvaluationData => ({
    questionTitle: "Explain the process of photosynthesis in plants and describe the role of chlorophyll in this process.",
    maxScore: 10,
    extractedInfo: "The student has explained that photosynthesis is a process where plants convert carbon dioxide and water into glucose and oxygen using sunlight. The answer mentions that this process takes place in the leaves and involves the green pigment called chlorophyll which captures light energy.",
    keypoints: [
      "Definition of photosynthesis correctly stated",
      "Reactants (CO₂ and H₂O) and products (glucose and O₂) identified",
      "Role of sunlight as energy source mentioned",
      "Chlorophyll identified as the light-absorbing pigment",
      "Location of photosynthesis in chloroplasts mentioned"
    ],
    evaluationScore: 7,
    missing: [
      "Light-dependent and light-independent reactions not explained",
      "Chemical equation not provided",
      "Stomata's role in gas exchange not mentioned"
    ],
    rational: "The student demonstrates a good foundational understanding of photosynthesis. The answer correctly identifies the basic components and process of photosynthesis. However, the response lacks depth in explaining the detailed mechanisms such as the two stages of photosynthesis (light-dependent and light-independent reactions). The role of chlorophyll is mentioned but could be elaborated further to include how it absorbs specific wavelengths of light. Overall, a competent answer that meets most basic requirements but misses some advanced concepts expected at this level."
  })

  // Header token count: show selected workspace tokens when available, otherwise sum of all workspaces
  const headerTokenCount = selectedWorkspace
    ? (selectedWorkspace.totalTokenUsage || 0)
    : workspaces.reduce((sum, w) => sum + (w.totalTokenUsage || 0), 0)

  // Mock answer sheet images
  const generateMockAnswerSheets = (): AnswerSheetPage[] => {
    return [
      { pageNumber: 1, imageUrl: ocrAnswerSheet1 },
      { pageNumber: 2, imageUrl: ocrAnswerSheet2 },
      { pageNumber: 3, imageUrl: ocrAnswerSheet3 },
    ]
  }

  const questionListAbortRef = React.useRef<AbortController | null>(null)
  const questionListLastKeyRef = React.useRef<string | null>(null)
  const questionListLastAtRef = React.useRef<number>(0)

  // Load question list for the current subject from ICME_OCR/question-list
  useEffect(() => {
    if (!subjectsLoaded) return
    let mounted = true
    // Debounce start: avoids React 18 StrictMode double-effect from hitting the backend twice.
    const t = window.setTimeout(() => {
      void (async () => {
        // Declared outside the try block so the `finally` below can still see
        // it: only the most recently started request is allowed to clear the
        // page loader, so an older request aborted by a newer subject switch
        // doesn't turn the loader off while that newer fetch is still running.
        let requestKey = ''
        let startedLoading = false
        try {
          const { orgCode, custCode, userCode } = getFinalCodes()
          const subjectCode = resolveSubjectCode()
          const subjectName = resolveSubjectName()

          const payload = {
            OrgCode: orgCode,
            CustCode: custCode,
            SubjectCode: subjectCode,
          }

          requestKey = `${orgCode}|${custCode}|${subjectCode}`
          const now = Date.now()

          // Ignore duplicate triggers for the same subject in a short window.
          if (questionListLastKeyRef.current === requestKey && (now - questionListLastAtRef.current) < 1000) {
            return
          }
          questionListLastKeyRef.current = requestKey
          questionListLastAtRef.current = now
          startedLoading = true
          setQuestionListLoading(true)

          // Abort any previous in-flight question-list request.
          try {
            questionListAbortRef.current?.abort()
          } catch {
            // ignore
          }
          const controller = new AbortController()
          questionListAbortRef.current = controller

          const url = API_ENDPOINTS.questionList
          const res = await axios.get(url, { params: payload, signal: controller.signal })
          const data = res && res.data ? res.data : null

          // .NET API returns { ref1Data: [...], ref2Data: [] }; old API returns array directly
          const arr = Array.isArray(data) ? data : (Array.isArray(data?.ref1Data) ? data.ref1Data : [])
          if (mounted) setQuestionsEmpty(arr.length === 0)
          if (mounted && arr.length > 0) {
            const mapped = arr.map((q: any, index: number) => {
              const label = q.questionLabel ?? q.questionlabel ?? String(index + 1)
              const id = Number(label) || label
              const maxMarks = Number(q.marks ?? 0)

              const rawParts = Array.isArray(q.questionText) ? q.questionText : (Array.isArray(q.questiontext) ? q.questiontext : [])
              const questionRubric = Array.isArray(q.rubric) ? q.rubric : []

              const parts = rawParts.map((p: any, partIndex: number) => {
                const t = String(p.text ?? '')
                const m = p.marks != null ? Number(p.marks) : null

                let parsedPRubric = p.rubric;
                if (typeof p.rubric === 'string') {
                  try { parsedPRubric = JSON.parse(p.rubric); } catch (e) { }
                }

                let rawRubricForPart: any[] = [];
                if (Array.isArray(parsedPRubric)) {
                  rawRubricForPart = parsedPRubric;
                } else if (Array.isArray(questionRubric[partIndex])) {
                  rawRubricForPart = questionRubric[partIndex];
                } else if (questionRubric.length > 0 && !Array.isArray(questionRubric[0])) {
                  // Fallback for flat array at the question level
                  rawRubricForPart = questionRubric;
                }
                const rubric = rawRubricForPart.map((r: any) => ({
                  text: String(r.text ?? ''),
                  score: Number(r.score ?? 0),
                }))

                return {
                  text: t,
                  marks: m != null && !Number.isNaN(m) ? m : null,
                  rubric: rubric.length > 0 ? rubric : undefined,
                }
              })

              const textParts = parts.map((p: any) => (p.marks != null && Number(p.marks) !== 0 ? `${p.text} (${p.marks} marks)` : p.text))
              const text = textParts.join('\n')

              return {
                id,
                text,
                maxScore: maxMarks || 0,
                pages: 1,
                parts,
              }
            })

            setQuestions(mapped)
            setActiveQuestionIndex(0)
            setOcrActiveQuestionIndex(0)
            setPhase1VisitedQuestions(new Set([0]))
            setPhase2VisitedQuestions(new Set([0]))
          } else if (mounted) {
            setQuestions(defaultQuestionList)
          }
        } catch (err: any) {
          // Ignore cancels from abort/debounce.
          const name = String(err?.name ?? '')
          if (name === 'CanceledError' || name === 'AbortError') return

          console.error('Failed to fetch question list', err)
          if (mounted) {
            setQuestions(defaultQuestionList)
          }
        } finally {
          if (startedLoading && mounted && questionListLastKeyRef.current === requestKey) {
            setQuestionListLoading(false)
          }
        }
      })()
    }, 0)

    return () => {
      mounted = false
      window.clearTimeout(t)
      // Abort only real unmount / subject change requests.
      try {
        questionListAbortRef.current?.abort()
      } catch {
        // ignore
      }
    }
  }, [selectedSubject, subjectsLoaded])

  // Generate mock candidates for a workspace
  const generateMockCandidates = (count: number, folders?: UploadedFolder[]): CandidateData[] => {
    const centres = ["Delhi Centre", "Mumbai Centre", "Bangalore Centre", "Chennai Centre", "Kolkata Centre"]
    const addresses = [
      "123, Connaught Place, New Delhi - 110001",
      "456, Bandra West, Mumbai - 400050",
      "789, MG Road, Bangalore - 560001",
      "321, Anna Nagar, Chennai - 600040",
      "654, Park Street, Kolkata - 700016"
    ]

    return Array.from({ length: Math.min(count, 125) }, (_, index) => {
      const statuses = generateConsistentStatuses()
      return {
        id: `candidate-${index + 1}`,
        candidateName: `Candidate ${String(index + 1).padStart(3, '0')}`,
        registrationName: `REG${String(index + 1).padStart(6, '0')}`,
        centreName: centres[index % centres.length],
        centreAddress: addresses[index % addresses.length],
        phase1: statuses.phase1,
        phase2: statuses.phase2,
        phase3: statuses.phase3,
        rawSegmentationStatus: statuses.phase1 === 'approved' ? 3 : (statuses.phase1 === 'completed' ? 2 : (statuses.phase1 === 'in-progress' ? 1 : 0)),
        rawOcrStatus: statuses.phase2 === 'approved' ? 3 : (statuses.phase2 === 'completed' ? 2 : (statuses.phase2 === 'in-progress' ? 1 : 0)),
        rawMarkingStatus: (statuses.phase3 === 'approved' || statuses.phase3 === 'pending') ? 3 : (statuses.phase3 === 'completed' ? 2 : (statuses.phase3 === 'in-progress' ? 1 : 0)),
        isReview: 0,
        noqMarker: 0,
        multiqMarker: 0,
        segmentData: `Section A: Question 1-10\nSection B: Question 11-20\nSection C: Question 21-30\nTotal Segments: 30\nDetected Boundaries: 28/30`,
        ocrData: `Extracted Text Preview:\n\nQ1. What is the capital of India?\nA) Mumbai B) Delhi C) Chennai D) Kolkata\n\nQ2. Which river is longest in India?\nA) Ganga B) Yamuna C) Godavari D) Brahmaputra\n\nConfidence Score: 94.5%\nCharacter Recognition Rate: 98.2%`,
        segmentImages: generateMockSegmentImages(),
        evaluationData: generateMockEvaluationData(),
        evaluationMarks: statuses.hasEvaluationMarks ? Math.floor(Math.random() * 51) + 50 : undefined,
        maxMarks: 100,
        standardsMet: { met: Math.floor(Math.random() * 3) + 8, total: 10 },
        category: folders && folders.length > 1 ? folders[index % folders.length]?.name : undefined,
        quickApprove: statuses.quickApprove,
      }
    })
  }

  // Load real candidate data for a workspace from ICME_OCR/candidate-process-data
  // When `silent` is true, it refreshes data without showing page loader or clearing state.
  const loadCandidatesForWorkspace = async (workspace: Workspace, options?: { silent?: boolean; force?: boolean }) => {
    const silent = options?.silent === true
    // If any overlay/loader is active on the page, skip calling candidate-process-data.
    // Include page-level loaders, phase-specific loaders and upload overlays.
    const isAnyLoaderActiveNow = (
      pageLoading || workspaceValidationLoading || preparingFilesLoading || firstUploadPdfsLoading ||
      candidateInfoLoading || phase1ApproveSaving || ocrApproveSaving || evaluationScoreSaving || reEvaluationSubmitting ||
      phase1Loading || isUploading || isCreatingWorkspace || isValidatingName || isUploadingAddedFiles || isBackgroundUploading
    )
    // `force` is for a refresh that must run once a submission has finished. Those
    // callers await a long chain, so the flags captured when they started can be
    // stale; skipping here would leave the new rows off the table.
    if (isAnyLoaderActiveNow && options?.force !== true) return
    try {
      // Show page-level loader while fetching candidate/process data
      if (!silent) setPageLoading(true)
      setSelectedWorkspace(workspace)
      if (!silent) {
        setHasUploaded(false)
        setCandidates([])
      }

      const { orgCode, custCode, userCode } = getFinalCodes()
      const _subject_code_raw = resolveSubjectCode() || 'S1'
      // When standalone mode is ON, always use 'generic' (matches create-workspace & list-workspace)
      const subject_code = localStorage.getItem('standalone_mode') === '1' ? 'generic' : _subject_code_raw
      // Prefer the selected workspace's id (when numeric), otherwise fall back to session.
      // Also sync the selected numeric workspace id into sessionStorage for downstream calls.
      const workspaceIdFromWorkspace = (() => {
        const raw = String(workspace?.id ?? '').trim()
        if (/^\d+$/.test(raw)) return Number(raw)
        return null
      })()
      const workspaceIdRaw = sessionStorage.getItem('workspaceid') || sessionStorage.getItem('workspacesid') || null
      const workspaceIdFromSession = workspaceIdRaw ? (Number(workspaceIdRaw) || 0) : 0
      const workspaceId = workspaceIdFromWorkspace ?? workspaceIdFromSession
      if (workspaceIdFromWorkspace != null) {
        sessionStorage.setItem('workspaceid', String(workspaceIdFromWorkspace))
      }

      // Read persisted Quick Approve preferences for this workspace so the
      // 10s refresh doesn't reset them back to default false.
      const quickApproveWorkspaceKey = (workspaceId || workspaceId === 0)
        ? String(workspaceId)
        : String(workspace?.id ?? '')
      const persistedQuickApprove = quickApproveWorkspaceKey ? readQuickApproveMap(quickApproveWorkspaceKey) : {}
      const nextPersistedQuickApprove: Record<string, boolean> = { ...persistedQuickApprove }
      // Build payload for candidate-process-data API
      const payload = {
        OrgCode: orgCode,
        CustCode: custCode,
        UserCode: userCode,
        SubjectCode: subject_code,
        WorkspaceId: workspaceId,
      }

      const res = await axios.get(API_ENDPOINTS.candidateProcessData, {
        params: payload,
        headers: {
          'Cache-Control': 'no-cache',
          'Pragma': 'no-cache',
          'Expires': '0',
        }
      })
      const data = res && res.data ? res.data : null

      const summaryArr: any[] = Array.isArray(data?.summary) ? data.summary : []
      let detailsArr: any[] = Array.isArray(data?.details) ? data.details : []

      // If the summary returns a userCode, update the selected workspace with it so ownership checks work correctly
      if (summaryArr.length > 0) {
        const firstSummary = summaryArr[0];
        const apiUserCode = (firstSummary.userCode || firstSummary.usercode || firstSummary.UserCode || firstSummary.createdby || firstSummary.createdBy || '').toString().trim();
        if (apiUserCode && workspace.userCode !== apiUserCode) {
          workspace.userCode = apiUserCode;
          setSelectedWorkspace({ ...workspace, userCode: apiUserCode });

          // Also try to update it in the main workspaces list so it stays correct
          setWorkspaces(prev => prev.map(w => w.id === workspace.id ? { ...w, userCode: apiUserCode } : w));
        }
      }

      // Derive folder-level information from summary
      // If foldername is empty/null, do NOT create a synthetic/"Uncategorized" folder;
      // in that case we want candidates to appear directly without grouping.
      let derivedFolders: UploadedFolder[] | undefined
      if (summaryArr.length > 0) {
        const folders: UploadedFolder[] = []
        summaryArr.forEach((s: any, idx: number) => {
          const rawName = (s.folderName ?? s.foldername ?? '').toString().trim()
          if (!rawName) return
          folders.push({
            id: `f-summary-${idx}`,
            name: rawName,
            fileCount: Number(s.candidateCount ?? s.candidatecount ?? 0),
            totalCandidateCount: typeof (s.totalCandidateCount ?? s.totalcandidatecount) === 'number'
              ? Number(s.totalCandidateCount ?? s.totalcandidatecount)
              : undefined,
            size: 0,
            type: 'folder',
            uploadedAt: new Date().toISOString().split('T')[0],
          })
        })
        derivedFolders = folders.length > 0 ? folders : undefined
      }

      // Map status codes (0,1,2) to PhaseStatus strings
      const mapStatusCodeToPhaseStatus = (code: any, phase: 'segmentation' | 'ocr' | 'evaluation'): PhaseStatus => {
        const n = Number(code)
        // Backend uses 3 to indicate "pending approval" (show Approve button)
        if (n === 3) return 'pending'
        if (n === 2) return 'completed'
        // With no stage downstream of Segmentation, status 1 IS the finished
        // state - there is nothing left for the candidate to move on to. Every
        // other configuration keeps the original in-progress meaning.
        if (n === 1) return (phase === 'segmentation' && isSegmentationOnly) ? 'completed' : 'in-progress'

        // When no progress has started (code 0), expose a phase-specific
        // "yet to" status so the UI and filters can distinguish
        if (phase === 'segmentation') return 'yet-to-segmentation'
        if (phase === 'ocr') return 'yet-to-ocr'
        if (phase === 'evaluation') return 'yet-to-evaluation'

        return 'pending'
      }

      const realCandidates: CandidateData[] = detailsArr.map((d: any, index: number) => {
        const rawSegmentationStatus = Number(d.segmentationStatus ?? d.segmentationstatus ?? 0)
        const rawOcrStatus = Number(d.ocrStatus ?? d.ocrstatus ?? 0)
        const rawMarkingStatus = Number(d.markingStatus ?? d.markingstatus ?? 0)
        const rawApprovedStatus = Number(d.approvedStatus ?? d.approvedstatus ?? 0)

        const phase1Base = mapStatusCodeToPhaseStatus(d.segmentationStatus ?? d.segmentationstatus, 'segmentation')
        // Backend can keep segmentationstatus=3 (pending) even after approval.
        // Use approvedstatus to render an explicit Approved state only if it was pending.
        const phase1: PhaseStatus = (rawApprovedStatus === 1 && phase1Base === 'pending') ? 'approved' : phase1Base
        const phase2 = mapStatusCodeToPhaseStatus(d.ocrStatus ?? d.ocrstatus, 'ocr')
        const phase3 = mapStatusCodeToPhaseStatus(d.markingStatus ?? d.markingstatus, 'evaluation')
        // candidate-process-data may return evaluation scoring in several shapes:
        // `obtainedscore` / `maxscore`, `obtainedScore`, `score`, or nested
        // inside `final_score.obtained_score`. Treat 0 as a valid score.
        // Some backends place evaluation/final score inside a nested processdata
        // object. Try to read a canonical `proc` reference for fallbacks.
        const proc = ((d.processData ?? d.processdata) && typeof (d.processData ?? d.processdata) === 'object')
          ? (d.processData ?? d.processdata)
          : (Array.isArray(d.data) && d.data.length > 0 && d.data[0].processdata && typeof d.data[0].processdata === 'object')
            ? d.data[0].processdata
            : null

        const finalScoreObj = proc && proc.final_score ? proc.final_score : (d.final_score ?? null)

        const obtainedScoreFromApi = (
          d.obtainedScore ?? d.obtainedscore ?? d.score
          ?? (finalScoreObj && (finalScoreObj.obtained_score ?? finalScoreObj.obtainedScore))
          ?? d.finalscore
        )
        const hasScore = obtainedScoreFromApi !== null && obtainedScoreFromApi !== undefined

        const standardsTotal = Number(d.standardCount ?? d.standardcount ?? proc?.standards?.total ?? proc?.standards_total ?? 0)
        const standardsMet = Number(d.metStandardCount ?? d.metstandardcount ?? proc?.standards?.met ?? proc?.standards_met ?? 0)

        // Use maxscore from API for the evaluation denominator when available;
        // fall back to proc.final_score.max_score, standardsTotal or 100.
        const maxScoreFromApi = (d.maxScore ?? d.maxscore) != null
          ? Number(d.maxScore ?? d.maxscore)
          : (finalScoreObj && (finalScoreObj.max_score ?? finalScoreObj.maxScore))
        const maxMarks = maxScoreFromApi ?? (standardsTotal || 100)

        // Only expose evaluationMarks (and therefore the X/Y chip in UI)
        // once marking is completed or approved. For markingstatus 0 or 1 the table
        // will show the appropriate status badge instead of 0/max. Also show
        // the score when the candidate is approved so users see final marks.
        const evaluationMarks = (phase3 === 'completed' || phase3 === 'approved' || phase3 === 'pending') && hasScore
          ? Number(obtainedScoreFromApi)
          : undefined

        const id = String(d.registrationNumber ?? d.registrationnumber ?? `candidate-${index + 1}`)
        // Quick Approve toggle is enabled when the configured final stage is 2 or higher OR if any specific marker is present.
        const hasMarker = (Number((d.isReview ?? 0)) === 1 || Number((d.noqMarker ?? 0)) === 1 || Number((d.multiqMarker ?? 0)) === 1);
        const stages = effectiveWorkflowStages;
        const isFinalStageReady = stages.evaluation
          ? rawMarkingStatus >= 2
          : stages.ocr
            ? rawOcrStatus >= 2
            : (stages.segmentation || stages.indexing)
              ? (rawSegmentationStatus >= 2 || rawApprovedStatus === 1)
              : false;

        // Video (OCR+Evaluation, no Segmentation/Indexing): the candidate's
        // first video file and an approximate length, read straight from this
        // same response's ocr_extracted_text instead of a per-candidate fetch.
        let videoFileName: string | undefined
        let videoDurationSec: number | undefined
        if (proc?.ocr_extracted_text && typeof proc.ocr_extracted_text === 'object') {
          outer:
          for (const perQuestion of Object.values(proc.ocr_extracted_text as Record<string, any>)) {
            if (!perQuestion || typeof perQuestion !== 'object') continue
            for (const [path, value] of Object.entries(perQuestion as Record<string, any>)) {
              if (!isVideoFileName(path)) continue
              videoFileName = String(path).split(/[/\\]+/).pop()
              const segs = (value && typeof value === 'object') ? (value as any).segments : null
              const lastEnd = Array.isArray(segs) && segs.length > 0 ? segs[segs.length - 1]?.end : null
              if (typeof lastEnd === 'number') videoDurationSec = lastEnd
              break outer
            }
          }
        }

        const eligibleForQuickApprove = isFinalStageReady || hasMarker;
        const persisted = Boolean(persistedQuickApprove[id])
        const isNoq = Number(d.noqMarker ?? d.noqmarker ?? 0) === 1;
        let quickApprove = eligibleForQuickApprove ? persisted : false;
        if (isNoq) quickApprove = true;

        // If a candidate becomes ineligible after refresh, clear the persisted
        // Quick Approve flag so UI doesn't flip-flop unexpectedly.
        if (!eligibleForQuickApprove && nextPersistedQuickApprove[id] && !isNoq) {
          delete nextPersistedQuickApprove[id]
        }

        return {
          id,
          candidateName: String(d.registrationNumber ?? d.registrationnumber ?? `Candidate ${index + 1}`),
          registrationName: String(d.registrationNumber ?? d.registrationnumber ?? ''),
          centreName: workspace.name,
          centreAddress: '',
          phase1,
          phase2,
          phase3,
          rawSegmentationStatus,
          rawApprovedStatus,
          rawOcrStatus,
          rawMarkingStatus,
          isReview: Number(d.isReview ?? d.isreview ?? 0),
          noqMarker: Number(d.noqMarker ?? d.noqmarker ?? 0),
          multiqMarker: Number(d.multiqMarker ?? d.multiqmarker ?? 0),
          segmentData: '',
          ocrData: '',
          segmentImages: [],
          evaluationData: generateMockEvaluationData(),
          evaluationMarks,
          maxMarks,
          standardsMet: { met: standardsMet, total: standardsTotal },
          category: (d.folderName ?? d.foldername) ? String(d.folderName ?? d.foldername).trim() || undefined : undefined,
          quickApprove,
          userCode: String(d.userCode ?? d.usercode ?? d.UserCode ?? d.Usercode ?? ''),
          videoFileName,
          videoDurationSec,
        }
      })

      // Persist any cleanup we did for ineligible candidates.
      if (quickApproveWorkspaceKey) {
        const prevKeys = Object.keys(persistedQuickApprove)
        const nextKeys = Object.keys(nextPersistedQuickApprove)
        if (prevKeys.length !== nextKeys.length) {
          writeQuickApproveMap(quickApproveWorkspaceKey, nextPersistedQuickApprove)
        }
      }

      const updatedWorkspace: Workspace = {
        ...workspace,
        candidateCount: realCandidates.length,
        // Only use derivedFolders when we actually have non-empty folder names;
        // otherwise clear uploadedFolders so the UI shows a flat candidate list.
        uploadedFolders: derivedFolders && derivedFolders.length > 0 ? derivedFolders : undefined,
        totalTokenUsage: typeof (summaryArr[0]?.totalTokenUsage ?? summaryArr[0]?.totaltokenusage) === 'number'
          ? Number(summaryArr[0]?.totalTokenUsage ?? summaryArr[0]?.totaltokenusage)
          : workspace.totalTokenUsage,
      }

      setSelectedWorkspace(updatedWorkspace)
      setWorkspaces(prev => prev.map(w => (w.id === workspace.id ? updatedWorkspace : w)))

      setFolderName(updatedWorkspace.name)
      setFileCount(updatedWorkspace.candidateCount)
      setTotalFileSize(updatedWorkspace.totalSize)

      if (realCandidates.length > 0) {
        setCandidates(realCandidates)
        setHasUploaded(true)
        // Track when each candidate first enters in-progress for stall detection
        setInProgressSince(prev => {
          const next = { ...prev }
          const now = Date.now()
          realCandidates.forEach(c => {
            const isInProgress = c.phase1 === 'in-progress' || c.phase2 === 'in-progress' || c.phase3 === 'in-progress'
            if (isInProgress && !next[c.id]) next[c.id] = now
            if (!isInProgress) delete next[c.id]
          })
          return next
        })
      } else {
        // No candidate data returned from backend: show "No candidates found"
        // by keeping candidates empty but marking hasUploaded true so the
        // table renders the "No candidates found matching your filters" message.
        setCandidates([])
        setHasUploaded(true)
      }

      // If backend summary provides folder counts, compute total reported candidates
      const responseTotal = (derivedFolders && derivedFolders.length > 0)
        ? derivedFolders.reduce((sum, f) => sum + (Number(f.fileCount || 0)), 0)
        : (detailsArr.length || 0)

      // Expected count: prefer the workspace.candidateCount (what we sent when creating the workspace),
      // otherwise fall back to the pending count tracked during upload pipeline.
      const expectedCount = Number(updatedWorkspace.candidateCount || pendingWorkspaceCandidateCount || 0)

      // Additional stop condition: if the backend returned details and every
      // candidate's `markingstatus` is `2` (i.e. marking completed), stop
      // polling. This ensures we only stop when all candidates are fully
      // marked, not merely when counts match.
      const allMarked = Array.isArray(detailsArr) && detailsArr.length > 0 && detailsArr.every((d: any) => Number(d?.markingStatus ?? d?.markingstatus) === 2)
      if (allMarked) {
        stopCandidatePolling()
        // toast.success('All candidates marked for this workspace')
      }
    } catch (err) {
      console.error('Failed to load candidate process data', err)
      if (!silent) {
        toast.error('Failed to load candidate data, showing sample data instead')
        const fallback = generateMockCandidates(selectedWorkspace?.candidateCount || 0, selectedWorkspace?.uploadedFolders)
        setCandidates(fallback)
        setHasUploaded(true)
      }
    } finally {
      // Hide page-level loader once candidate/process data fetch completes
      if (!silent) setPageLoading(false)
    }
  }

  const handleConfirmDeleteWorkspace = async () => {
    const idsToDelete = pendingDeleteWorkspace
      ? [pendingDeleteWorkspace.id]
      : Array.from(selectedWorkspaceIds)

    if (idsToDelete.length === 0) return

    setIsDeletingWorkspace(true)
    setPageLoading(true)
    let anySuccess = false

    const deletableIds: string[] = []
    const deletableNames: string[] = []

    for (const wsId of idsToDelete) {
      const ws = workspaces.find(w => w.id === wsId)
      if (!ws) continue

      const currentCandidateCount = ws.candidateCount || 0
      if (currentCandidateCount > 0) {
        toast.error(`Cannot delete workspace "${ws.name}" — it has candidates.`)
        continue
      }
      deletableIds.push(String(ws.id))
      deletableNames.push(ws.name)
    }

    if (deletableIds.length > 0) {
      try {
        const payload = { workspaceId: deletableIds.join(',') }
        const res = await axios.post(API_ENDPOINTS.deleteWorkspace, payload)
        const data = res && res.data ? res.data : null

        if (data && (data.status === 'S001' || data.responseCode === 'S001' || data.ResponseCode === 'S001' || data.status === 'success')) {
          toast.success(data.message || data.responseMessage || data.ResponseMessage || `Workspace(s) "${deletableNames.join(', ')}" deleted successfully`)
          anySuccess = true
        } else {
          const msg = data?.message || data?.responseMessage || data?.ResponseMessage || `Cannot delete workspace(s) "${deletableNames.join(', ')}".`
          toast.error(msg)
        }
      } catch (err) {
        console.error('Failed to delete workspace(s)', err)
        toast.error(`An error occurred while deleting "${deletableNames.join(', ')}". Please try again.`)
      }
    }

    setIsDeletingWorkspace(false)
    setPageLoading(false)
    setPendingDeleteWorkspace(null)
    setShowWorkspaceDeleteConfirm(false)
    setSelectedWorkspaceIds(new Set())

    if (anySuccess) {
      await refreshWorkspaces({ force: true })
      await refreshSubjects()
    }
  }

  // Keep latest loader function for interval callbacks to avoid stale-closure issues.
  const loadCandidatesForWorkspaceRef = React.useRef(loadCandidatesForWorkspace)
  React.useEffect(() => {
    loadCandidatesForWorkspaceRef.current = loadCandidatesForWorkspace
  }, [loadCandidatesForWorkspace])

  const handleQuickApproveChange = React.useCallback((candidateId: string, checked: boolean) => {
    setCandidates(prev => prev.map(c => c.id === candidateId ? { ...c, quickApprove: checked } : c))

    // Store per active workspace so polling refresh keeps the choice.
    const workspaceIdFromSession = sessionStorage.getItem('workspaceid') || sessionStorage.getItem('workspacesid')
    const workspaceId = (workspaceIdFromSession && String(workspaceIdFromSession).trim() !== '')
      ? String(workspaceIdFromSession)
      : String(selectedWorkspace?.id ?? '')
    if (!workspaceId) return

    const current = readQuickApproveMap(workspaceId)
    const next = { ...current }
    if (checked) {
      next[candidateId] = true
    } else {
      delete next[candidateId]
    }
    writeQuickApproveMap(workspaceId, next)
  }, [selectedWorkspace])

  const renderQuickApproveToggle = (candidate: any) => {
    const isNoq = Number((candidate as any).noqMarker ?? 0) === 1;
    const incompleteStatuses = ['yet-to-segmentation', 'yet-to-ocr', 'yet-to-evaluation', 'in-progress'];
    const hasIncomplete1 = (effectiveWorkflowStages.segmentation || effectiveWorkflowStages.indexing) && incompleteStatuses.includes(candidate.phase1 as any);
    const hasIncomplete2 = effectiveWorkflowStages.ocr && incompleteStatuses.includes(candidate.phase2 as any);
    const hasIncomplete3 = effectiveWorkflowStages.evaluation && incompleteStatuses.includes(candidate.phase3 as any);
    const hasIncompletePhase = hasIncomplete1 || hasIncomplete2 || hasIncomplete3;
    const disableForIncomplete = hasIncompletePhase && !isNoq;
    const isRerunning = runningOcrCandidates.has(candidate.id) || runningEvalCandidates.has(candidate.id);
    const finalDisabled = disableForIncomplete || isRerunning || isNoq;

    return (
      <TooltipProvider>
        <Tooltip>
          <TooltipTrigger asChild>
            <div className="inline-block">
              <Switch
                checked={candidate.quickApprove || false}
                onCheckedChange={(checked) => handleQuickApproveChange(candidate.id, checked)}
                disabled={finalDisabled}
                className="data-[state=checked]:bg-teal-600 disabled:opacity-50 disabled:cursor-not-allowed"
              />
            </div>
          </TooltipTrigger>
          {isNoq && (
            <TooltipContent side="bottom" className="text-xs py-1 px-2 bg-white border border-slate-200 rounded-md shadow-sm z-50">
              Not available: No Question Marker detected
            </TooltipContent>
          )}
          {disableForIncomplete && !isRerunning && !isNoq && (
            <TooltipContent side="bottom" className="text-xs py-1 px-2 bg-white border border-slate-200 rounded-md shadow-sm z-50">
              Not available while phase(s) are incomplete
            </TooltipContent>
          )}
          {isRerunning && (
            <TooltipContent side="bottom" className="text-xs py-1 px-2 bg-white border border-slate-200 rounded-md shadow-sm z-50">
              Not available during rerun
            </TooltipContent>
          )}
        </Tooltip>
      </TooltipProvider>
    );
  };

  const startCandidatePolling = React.useCallback((workspace: Workspace) => {
    stopCandidatePolling()
    // set next-poll timestamp so countdown UI can reflect remaining time
    candidateNextPollAtRef.current = Date.now() + CANDIDATE_POLL_INTERVAL_MS
    setPollCountdown(Math.ceil(CANDIDATE_POLL_INTERVAL_MS / 1000))

    candidatePollIntervalRef.current = window.setInterval(() => {
      void loadCandidatesForWorkspaceRef.current(workspace, { silent: true })
      // update next expected poll time after each poll
      candidateNextPollAtRef.current = Date.now() + CANDIDATE_POLL_INTERVAL_MS
      setPollCountdown(Math.ceil(CANDIDATE_POLL_INTERVAL_MS / 1000))
    }, CANDIDATE_POLL_INTERVAL_MS)
  }, [stopCandidatePolling])

  // Countdown updater (1s) to drive the UI countdown display
  React.useEffect(() => {
    const id = window.setInterval(() => {
      const next = candidateNextPollAtRef.current
      if (next == null) {
        setPollCountdown(Math.ceil(CANDIDATE_POLL_INTERVAL_MS / 1000))
        return
      }
      const secs = Math.max(0, Math.ceil((next - Date.now()) / 1000))
      setPollCountdown(secs)
    }, 1000)
    return () => clearInterval(id)
  }, [])

  // Stop polling when all background uploads are completed.
  React.useEffect(() => {
    if (uploadTotalFiles > 0 && uploadCompletedFiles >= uploadTotalFiles) {
      stopCandidatePolling()
    }
  }, [uploadTotalFiles, uploadCompletedFiles, stopCandidatePolling])

  // Pause candidate polling while any dialog/modal is open. When all dialogs
  // are closed, restart polling for the selected workspace and reset the
  // 15s interval so counting begins after the dialog is closed.
  React.useEffect(() => {
    const dialogOpen = Boolean(
      showCreateWorkspaceDialog ||
      showUploadConfirm ||
      showAddedFilesDialog ||
      showFolderFilesDialog ||
      showReuploadConfirm ||
      showReEvaluationDialog ||
      showSaveConfirmDialog ||
      showEvalInfoDialog ||
      phase1ReviewCandidate ||
      ocrReviewCandidate ||
      evaluationReviewCandidate ||
      detailCandidate ||
      standardsDialogCandidate
    )

    if (dialogOpen) {
      stopCandidatePolling()
      return
    }

    // No dialog open -> (re)start polling for the currently selected workspace.
    if (selectedWorkspace) {
      startCandidatePolling(selectedWorkspace)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    showCreateWorkspaceDialog,
    showUploadConfirm,
    showAddedFilesDialog,
    showFolderFilesDialog,
    showReuploadConfirm,
    showReEvaluationDialog,
    showSaveConfirmDialog,
    showEvalInfoDialog,
    phase1ReviewCandidate,
    ocrReviewCandidate,
    evaluationReviewCandidate,
    detailCandidate,
    standardsDialogCandidate,
    selectedWorkspace,
  ])

  // When switching workspaces, reset list filters so they don't carry over.
  React.useEffect(() => {
    setStatusFilter('all')
    setPhaseFilter('all')
  }, [selectedWorkspace?.id])

  const syncWorkspaceIdToSession = React.useCallback((workspace: Workspace | null) => {
    if (!workspace) return
    const raw = String(workspace.id ?? '').trim()
    if (/^\d+$/.test(raw)) {
      sessionStorage.setItem('workspaceid', raw)
    }
  }, [])

  const resetOcrSegmentEditingState = React.useCallback(() => {
    setEditingSegmentId(null)
    setEditedSegmentOcrText("")
    setSegmentOcrTexts({})
  }, [])

  /** Identifies one OCR cell: a single image as it appears under a single question. */
  const getSegmentEditKey = React.useCallback(
    (questionKey: string, imageUrl: string) => `${questionKey}::${imageUrl}`,
    []
  )

  const commitOcrEdit = React.useCallback((questionKey: string, imageUrl: string, nextText: string | { text: string; segments: VideoTranscriptSegment[] }) => {
    // Update display map
    setOcrExtractedTextByQuestion(prev => {
      const base = prev ? { ...prev } : {}
      const perQ = { ...(base[questionKey] || {}) }
      perQ[imageUrl] = nextText
      base[questionKey] = perQ
      return base
    })

    // Update raw map (preferred for saving to backend)
    setOcrExtractedTextByQuestionRaw(prev => {
      const base = prev ? { ...prev } : {}
      const rawPath = ocrImageUrlToRawPathByQuestion?.[questionKey]?.[imageUrl] || ''
      if (!rawPath) return base
      const perQ = { ...(base[questionKey] || {}) }
      perQ[rawPath] = nextText
      base[questionKey] = perQ
      return base
    })
  }, [ocrImageUrlToRawPathByQuestion])

  const getQuestionKey = React.useCallback((id: number | string | undefined, indexFallback: number): string => {
    const raw = String(id ?? '').trim()
    const match = raw.match(/\d+/)
    return (match?.[0] ?? String(indexFallback + 1)).trim()
  }, [])

  const buildAnswerSheetsFromPaths = React.useCallback((pagePaths: string[], reasonsData?: any[]): AnswerSheetPage[] => {
    const paths = Array.isArray(pagePaths) ? pagePaths.filter((p): p is string => typeof p === 'string') : []
    return paths.map((path, idx) => {
      let reason: string | undefined;
      if (reasonsData && Array.isArray(reasonsData)) {
        const found = reasonsData.find(r => r && r.path === path);
        if (found && found.reason) {
          reason = found.reason;
        }
      }
      return {
        pageNumber: idx + 1,
        imageUrl: toDisplayableImageUrl(path),
        sourcePath: path,
        label: path.split(/[/\\]+/).pop() || `Page ${idx + 1}`,
        isLocal: (/^[a-zA-Z]:\\\\/.test(path) || /^\\\\/.test(path) || toDisplayableImageUrl(path).startsWith('file://')),
        reason,
      };
    })
  }, [])

  const mapOcrExtractedToSegments = React.useCallback((questionKey: string): SegmentImage[] => {
    const map = ocrExtractedTextByQuestion?.[questionKey]
    if (!map) return []

    return Object.entries(map).map(([imageUrl, text], idx) => {
      const fileName = String(imageUrl ?? '').split(/[/\\]+/).pop() || `Image ${idx + 1}`
      // API may return either a plain string (legacy), an image ExtractionResult
      // ({ transcription, ... }), or a video VideoTranscriptionResult ({ text, segments }).
      const isRichObj = text !== null && typeof text === 'object'
      const transcription = isRichObj ? String((text as any).transcription ?? (text as any).text ?? '') : String(text ?? '')
      return {
        id: idx + 1,
        imageUrl: imageUrl,
        label: fileName,
        ocrText: transcription,
        ocrBlocks:       isRichObj ? ((text as any).blocks ?? [])        : [],
        ocrFigureCounts: isRichObj ? ((text as any).figure_counts ?? {}) : {},
        ocrTokens:       isRichObj ? ((text as any).tokens ?? {})         : {},
        ocrSubject:      isRichObj ? String((text as any).subject ?? '')  : '',
        ocrIssues:       isRichObj ? ((text as any).issues ?? [])         : [],
        ocrTranscriptionLatex: isRichObj ? String((text as any).transcription_latex ?? '') : '',
        ocrInterpretation:     isRichObj ? String((text as any).interpretation ?? '')      : '',
        transcriptSegments: (isRichObj && Array.isArray((text as any).segments)) ? (text as any).segments : undefined,
      }
    })
  }, [ocrExtractedTextByQuestion])

