                      const isNextQuestion = index === evalActiveQuestionIndex + 1
                      const isFreeNavigation = !evaluationReviewCandidate?.quickApprove
                      const isClickable = isFreeNavigation
                        ? true
                        : isCurrentQuestion || isPreviousQuestion || (isNextQuestion && phase3VisitedQuestions.has(evalActiveQuestionIndex))

                      const qKey = getQuestionKey(question.id, index)
                      const raw = phase1IndexingRecord?.["question_page_mapping"]?.[qKey]
